INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL VALUES('SYYHCKZQGZ','05', 'SQL','SELECT 1 FROM DUAL', 'portfolioCode,issuerCode','N','wp','C001',sysdate,'wp',sysdate);

DECLARE
---- 实时、买入预占、卖出预占
V_CONTENT_01_02_03 CLOB := 'SELECT
    NVL(SUM(NVL(VAL.MARKET_VALUE,0)),0) RVALUE,
    VAL.PORTFOLIO_ID || '','' || PRD.ISSUER RKEY
FROM PTL_SEC_PIERCE_VALUTION VAL
INNER JOIN FIN_PRODUCT PRD ON VAL.FINPROD_ID = PRD.FINPROD_ID
INNER JOIN FIN_PRODUCT_TYPE TYP ON TYP.FINPROD_ID = PRD.FINPROD_ID AND TYP.TYPE_8 IN (''F01'', ''F05'') AND ((PRD.FINPROD_TYPE2 = ''F01'' AND TYP.TYPE_9 NOT IN (''03'',''04'') ) or  PRD.FINPROD_TYPE2 = ''F07'')
INNER JOIN MST_CUSTOMER_INFO_ADD MCIA ON MCIA.CUSTOMER_ID = PRD.ISSUER
WHERE VAL.CDATE = date''${valDate}'' - 1 AND MCIA.CUSTOMER_OBJ_TYPE = ''12'' 
GROUP BY VAL.PORTFOLIO_ID,PRD.ISSUER';

----事后(日间)
V_CONTENT_04 CLOB := 'SELECT SUM(TRADE_AMT) as RVALUE, RKEY, RKEYCN FROM (
    SELECT
        SUM(NVL(VAL.MARKET_VALUE ,0)) TRADE_AMT, PRD.ISSUER RKEY, CST.CUSTOMER_NAME RKEYCN
    FROM PTL_SEC_PIERCE_VALUTION VAL
    INNER JOIN FIN_PRODUCT PRD ON VAL.FINPROD_ID = PRD.FINPROD_ID
    INNER JOIN FIN_PRODUCT_TYPE TYP ON TYP.FINPROD_ID = PRD.FINPROD_ID AND TYP.TYPE_8 IN (''F01'', ''F05'') AND ((PRD.FINPROD_TYPE2 = ''F01'' AND TYP.TYPE_9 NOT IN (''03'',''04'') ) or  PRD.FINPROD_TYPE2 = ''F07'')
    LEFT JOIN MST_CUSTOMER_INFO CST ON PRD.ISSUER = CST.CUSTOMER_ID
    LEFT JOIN MST_CUSTOMER_INFO_ADD MCIA ON MCIA.CUSTOMER_ID = CST.CUSTOMER_ID
    WHERE VAL.CDATE = date''${valDate}'' - 1 AND VAL.PORTFOLIO_ID IN ${portfolioCode}
    AND MCIA.CUSTOMER_OBJ_TYPE = ''12''
    GROUP BY PRD.ISSUER,CST.CUSTOMER_NAME
  UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T01'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T04'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T52'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T03'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T19'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T07'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T08'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T09'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T11'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T22'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T23'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T38'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T39'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) AS TRADE_AMT, t2.ISSUER RKEY, CST.CUSTOMER_NAME RKEYCN
    FROM TRD_PRODUCT_DEAL_ADD m
    INNER JOIN TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID
    INNER JOIN FIN_PRODUCT t2 ON t2.FINPROD_ID = n.FINPROD_ID AND t2.FINPROD_TYPE2 IN (''F01'',''F07'')
    INNER JOIN FIN_PRODUCT_TYPE t3 ON n.FINPROD_ID = t3.FINPROD_ID AND t3.BRANCH = 0 AND t3.TYPE_8 IN (''F01'', ''F05'')  AND ((t2.FINPROD_TYPE2 = ''F01'' AND t3.TYPE_9 NOT IN (''03'',''04'') ) or  t2.FINPROD_TYPE2 = ''F07'')
    LEFT JOIN MST_CUSTOMER_INFO CST ON t2.ISSUER = CST.CUSTOMER_ID
    LEFT JOIN MST_CUSTOMER_INFO_ADD MCIA ON MCIA.CUSTOMER_ID = CST.CUSTOMER_ID
    WHERE m.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE = DATE''${valDate}''
    AND MCIA.CUSTOMER_OBJ_TYPE = ''12''
    AND n.PS IN (''T01'', ''T02'', ''T03'', ''T04'', ''T19'', ''T07'', ''T08'', ''T09'', ''T11'', ''T52'', ''T22'', ''T23'', ''T38'', ''T39'')
    GROUP BY t2.ISSUER,CST.CUSTOMER_NAME
  UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T01'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T04'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T52'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T03'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T19'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T07'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T08'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T09'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T11'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T22'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T23'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T38'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T39'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) AS TRADE_AMT, t2.ISSUER RKEY, CST.CUSTOMER_NAME RKEYCN
    FROM TRD_PRODUCT_TEMP_DEAL_ADD m
    INNER JOIN TRD_PRODUCT_TEMP_DEAL n ON m.TRADE_ID = n.TRADE_ID
    INNER JOIN FIN_PRODUCT t2 ON t2.FINPROD_ID = n.FINPROD_ID AND t2.FINPROD_TYPE2 IN (''F01'',''F07'')
    INNER JOIN FIN_PRODUCT_TYPE t3 ON n.FINPROD_ID = t3.FINPROD_ID AND t3.BRANCH = 0 AND t3.TYPE_8 IN (''F01'', ''F05'') AND ((t2.FINPROD_TYPE2 = ''F01'' AND t3.TYPE_9 NOT IN (''03'',''04'') ) or  t2.FINPROD_TYPE2 = ''F07'')
    LEFT JOIN MST_CUSTOMER_INFO CST ON t2.ISSUER = CST.CUSTOMER_ID
    LEFT JOIN MST_CUSTOMER_INFO_ADD MCIA ON MCIA.CUSTOMER_ID = CST.CUSTOMER_ID
    WHERE m.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE = DATE''${valDate}''
    AND MCIA.CUSTOMER_OBJ_TYPE = ''12''
    AND n.PS IN (''T01'', ''T02'', ''T03'', ''T04'', ''T19'', ''T07'', ''T08'', ''T09'', ''T11'', ''T52'', ''T22'', ''T23'', ''T38'', ''T39'')
    GROUP BY t2.ISSUER,CST.CUSTOMER_NAME
  UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T01'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T04'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T52'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T03'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) AS TRADE_AMT, t2.ISSUER RKEY, CST.CUSTOMER_NAME RKEYCN
    FROM WFL_TRD_PRODUCT_DEAL_ADD m
    INNER JOIN WFL_TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID AND n.TRADE_STATUS != ''03''
    INNER JOIN SYS_WFL_BUSINESS_LIST swbl on n.WORKFLOW_ID = swbl.SEQ_NO and swbl.PROCESS_STATE != ''BACK''
    INNER JOIN FIN_PRODUCT t2 ON t2.FINPROD_ID = n.FINPROD_ID AND t2.FINPROD_TYPE2 IN (''F01'',''F07'')
    INNER JOIN FIN_PRODUCT_TYPE t3 ON n.FINPROD_ID = t3.FINPROD_ID AND t3.BRANCH = 0 AND t3.TYPE_8 IN (''F01'', ''F05'') AND ((t2.FINPROD_TYPE2 = ''F01'' AND t3.TYPE_9 NOT IN (''03'',''04'') ) or  t2.FINPROD_TYPE2 = ''F07'')
    LEFT JOIN MST_CUSTOMER_INFO CST ON t2.ISSUER = CST.CUSTOMER_ID
    LEFT JOIN MST_CUSTOMER_INFO_ADD MCIA ON MCIA.CUSTOMER_ID = CST.CUSTOMER_ID
    WHERE m.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE = DATE''${valDate}''
    AND MCIA.CUSTOMER_OBJ_TYPE = ''12''
    AND n.PS IN (''T01'', ''T02'', ''T03'', ''T04'',''T52'')
    GROUP BY t2.ISSUER,CST.CUSTOMER_NAME
  UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) AS TRADE_AMT, t2.ISSUER RKEY, CST.CUSTOMER_NAME RKEYCN
    FROM WFL_TRD_PRODUCT_DEAL_ADD m
    INNER JOIN WFL_TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID AND n.TRADE_STATUS != ''03''
    INNER JOIN SYS_WFL_BUSINESS_LIST swbl on n.WORKFLOW_ID = swbl.SEQ_NO and swbl.PROCESS_STATE != ''BACK''
    INNER JOIN FIN_PRODUCT t2 ON t2.FINPROD_ID = n.FINPROD_ID AND t2.FINPROD_TYPE2 IN (''F01'',''F07'')
    INNER JOIN FIN_PRODUCT_TYPE t3 ON n.FINPROD_ID = t3.FINPROD_ID AND t3.BRANCH = 0 AND t3.TYPE_8 IN (''F01'', ''F05'') AND ((t2.FINPROD_TYPE2 = ''F01'' AND t3.TYPE_9 NOT IN (''03'',''04'') ) or  t2.FINPROD_TYPE2 = ''F07'')
    LEFT JOIN MST_CUSTOMER_INFO CST ON t2.ISSUER = CST.CUSTOMER_ID
    LEFT JOIN MST_CUSTOMER_INFO_ADD MCIA ON MCIA.CUSTOMER_ID = CST.CUSTOMER_ID
    WHERE n.counter_id IN ${portfolioCode} AND n.TRADE_DATE = DATE''${valDate}''
    AND n.PS = ''T02'' AND MCIA.CUSTOMER_OBJ_TYPE = ''12''
    AND EXISTS (SELECT 1 FROM SYS_PARA WHERE PARA_CODE = ''is_auto_generate_negate_deal'' AND PARAM_VALUE = ''Y'')
    GROUP BY t2.ISSUER,CST.CUSTOMER_NAME
) GROUP BY RKEY, RKEYCN';

----事后(日终)
V_CONTENT_05 CLOB := 'SELECT
    NVL(SUM(NVL(VAL.MARKET_VALUE ,0)), 0) RVALUE, PRD.ISSUER RKEY, CST.CUSTOMER_NAME RKEYCN
FROM PTL_SEC_PIERCE_VALUTION VAL
INNER JOIN FIN_PRODUCT PRD ON VAL.FINPROD_ID = PRD.FINPROD_ID
INNER JOIN FIN_PRODUCT_TYPE TYP ON TYP.FINPROD_ID = PRD.FINPROD_ID AND TYP.TYPE_8 IN (''F01'', ''F05'') AND ((PRD.FINPROD_TYPE2 = ''F01'' AND TYP.TYPE_9 NOT IN (''03'',''04'') ) or  PRD.FINPROD_TYPE2 = ''F07'')
LEFT JOIN MST_CUSTOMER_INFO CST ON PRD.ISSUER = CST.CUSTOMER_ID
LEFT JOIN MST_CUSTOMER_INFO_ADD MCIA ON MCIA.CUSTOMER_ID = CST.CUSTOMER_ID
WHERE VAL.CDATE = date''${valDate}'' AND VAL.PORTFOLIO_ID IN ${portfolioCode} 
AND MCIA.CUSTOMER_OBJ_TYPE = ''12''
GROUP BY PRD.ISSUER,CST.CUSTOMER_NAME';
BEGIN
    UPDATE RSK_ISUP_INDICATOR_PARA_DTL SET CONTENT = V_CONTENT_01_02_03 WHERE PARA_CODE = 'SYYHCKZQGZ' and PARA_GRANULARITY in('01','02','03');

    UPDATE RSK_ISUP_INDICATOR_PARA_DTL SET CONTENT = V_CONTENT_04 WHERE PARA_CODE = 'SYYHCKZQGZ' and PARA_GRANULARITY ='04';

    UPDATE RSK_ISUP_INDICATOR_PARA_DTL SET CONTENT = V_CONTENT_05 WHERE PARA_CODE = 'SYYHCKZQGZ' and PARA_GRANULARITY = '05';
END;
/

